"use strict";
const fs = require("node:fs");
const path = require("node:path");
const cp = require("node:child_process");
const crypto = require("node:crypto");
const root = __dirname;
const progress = JSON.parse(fs.readFileSync(path.join(root, "progress.json")));
if (progress.count !== 42) throw new Error("Run after every measured model trial; no benchmark contention");
const trials = progress.completed.filter((r) => r.task.startsWith("humanize-"));
if (trials.length !== 12) throw new Error("Expect all twelve humanize artifacts");
const hash = (bytes) => crypto.createHash("sha256").update(bytes).digest("hex");
const python = path.join(root, "venvs/humanize/bin/python");
const { parseReport } = require(path.join(root, "sources/optimized/docs/eval/tools/run-trial.js"));
const results = [];
for (const receipt of trials) {
  const id = `${receipt.task}--${receipt.cell}--r${receipt.repetition}`;
  const trial = path.join(root, "trials", id);
  const original = path.join(trial, "runs", receipt.task, `${receipt.cell}-r${receipt.repetition}`);
  const dest = path.join(root, "i18n-quality", id);
  if (fs.existsSync(dest)) throw new Error("Refusing to overwrite an earlier check: " + id);
  fs.cpSync(original, dest, { recursive: true, filter: (file) => ![".git", ".pytest_cache", "__pycache__"].includes(path.basename(file)) });
  const env = { ...process.env, PYTHONDONTWRITEBYTECODE: "1", PYTHONPATH: path.join(dest, "src") };
  const compile = cp.spawnSync("bash", ["scripts/generate-translation-binaries.sh"], { cwd: dest, env, encoding: "utf8", timeout: 30000 });
  fs.writeFileSync(path.join(dest, "translation-build.log"), (compile.stdout || "") + (compile.stderr || ""));
  const junit = path.join(dest, "i18n.xml");
  const test = compile.status === 0 && !compile.error
    ? cp.spawnSync(python, ["-m", "pytest", "-q", "--tb=short", "--maxfail=0", "-p", "no:cacheprovider", `--junitxml=${junit}`, "tests/test_i18n.py"], { cwd: dest, env, encoding: "utf8", timeout: 30000 })
    : { status: null, stdout: "", stderr: "Translation compilation failed; tests not run" };
  fs.writeFileSync(path.join(dest, "i18n-test.log"), (test.stdout || "") + (test.stderr || ""));
  const report = parseReport(junit);
  const passed = compile.status === 0 && !compile.error && test.status === 0 && !test.error
    && !report.report_error && report.passed > 0 && report.failed === 0 && report.errors === 0 && report.skipped === 0;
  const sourceFiles = JSON.parse(fs.readFileSync(receipt.result_file)).diff.src_files;
  const sources = sourceFiles.map((file) => ({ file, sha256: hash(fs.readFileSync(path.join(dest, file))),
    original_matches: fs.readFileSync(path.join(dest, file)).equals(fs.readFileSync(path.join(original, file))) }));
  const row = { task: receipt.task, cell: receipt.cell, run: receipt.repetition, passed, compile_exit: compile.status,
    test_exit: test.status, report, sources, junit_sha256: fs.existsSync(junit) ? hash(fs.readFileSync(junit)) : null };
  results.push(row);
  console.log(JSON.stringify({ task: row.task, cell: row.cell, run: row.run, passed, tests: report.passed, skipped: report.skipped }));
}
fs.writeFileSync(path.join(root, "i18n-probes.json"), JSON.stringify({
  kind: "Uniform translation coverage check frozen before all model trials; exact procedure retained from the previous round",
  predeclared_numeric_protocol_unchanged: true,
  amendment: JSON.parse(fs.readFileSync(path.join(root, "protocol/i18n-amendment.json"))),
  methodology: "After all timed trials, copy every humanize artifact, compile translation resources, run the same existing tests/test_i18n.py with the unchanged baseline venv; no model rerun, no change to measured artifacts or original grading",
  source: fs.readFileSync(__filename, "utf8"), results,
}, null, 2));
